TITLE='Evolving Robust Instructions and Adaptive Format Ensembles for LLM Question Answering'
def H(text,level=2):return {'type':'heading','level':level,'text':text}
def P(text,small=False):return {'type':'paragraph','text':text,'small':small}
def T(headers,rows,caption,weights=None):return {'type':'table','headers':headers,'rows':rows,'caption':caption,'weights':weights or [1]*len(headers)}
def F(path,caption):return {'type':'figure','path':str(path),'caption':caption}
def pct(v):return f'{100*float(v):.2f}'

def historical_figures(h):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    target=ROOT/'report/figures';target.mkdir(parents=True,exist_ok=True)
    fig,ax=plt.subplots(figsize=(7,3.8));rs=h['study1']['summary'];ax.bar([r['condition'] for r in rs],[r['seen_all_correct']*100 for r in rs],yerr=[r['seen_all_correct_sd']*100 for r in rs],capsize=4,color=['#718596','#5693a7','#5693a7','#5693a7','#c27351']);ax.set(xlabel='Study1 condition',ylabel='All-five-correct questions (%)',title='Study1: robustness fitness did not beat controls');fig.tight_layout();fig.savefig(target/'study1_robustness.png',dpi=180);plt.close(fig)
    fig,ax=plt.subplots(figsize=(7,3.8));rs=[r for r in h['followup']['summary'] if r['method'] in ('G0','G1','G2','ordered_triple')];ax.bar([r['method'] for r in rs],[r['mean_calls'] for r in rs],yerr=[r['mean_calls_sd'] for r in rs],capsize=4,color='#5693a7');ax.set(ylabel='Mean calls (previous held-out1000)',title='Follow-up: fitted-seed cost and simple stopping');fig.tight_layout();fig.savefig(target/'followup_calls.png',dpi=180);plt.close(fig)

def blocks(final=None):
    h=load('historical_summary');references=read_json(ROOT/'docs/references.json');historical_figures(h);b=[]
    b += [H(TITLE,1),P('DSAI6707 Advanced Computational Intelligence | Individual Research Project | Completed-project report' if final else 'DSAI6707 Advanced Computational Intelligence | Report scaffold: final reserved-pool results pending'),
      P('Course deadline:15November2026. The original pre-experiment proposal is preserved verbatim as supplementary material; its earlier personal planning dates do not supersede the course brief.',True),H('Abstract')]
    if final:
        sm={r['method']:r for r in final['summary']};primary=next(r for r in final['comparisons'] if r['role']=='primary_methodological');practical=next(r for r in final['comparisons'] if r['role']=='primary_practical')
        text=f"We study two evolutionary-computation adaptations for a frozen Qwen2.5-3B-Instruct model: all-presentations-correct fitness for instruction evolution, and complementary-error/whole-policy-utility mutation for adaptive presentation-query policies. Study1's robust objective underperformed random and augmented-average controls on1109 ARC-Challenge questions. Study2 and a controlled five-seed repair found no extra benefit from utility guidance over simpler controls. A final frozen evaluation uses1000 newly held-out OpenBookQA training questions, kept unused through subsequent development diagnostics. G2 minus G1 final accuracy is{primary['accuracy']['difference']:+.3f} percentage points, call difference{primary['calls']['difference']:+.5f}, and utility difference{primary['utility']['difference']:+.6f}. Ordered stopping achieves{pct(sm['ordered_triple']['accuracy_mean'])}% at{sm['ordered_triple']['calls_mean']:.3f} calls, versus{pct(sm['fixed_three']['accuracy_mean'])}% at3 calls for its fixed triple. Their exact answer vectors are {'identical' if final['integrity']['fixed_vote_and_ordered_predictions_identical'] else 'different; the integrity limitation is explicitly reported'}. We distinguish ensemble accuracy, stopping efficiency, search consistency and utility guidance; no publication-level novelty or overall capability ceiling is claimed."
    else:text='This report integrates two completed evolutionary LLM studies, one controlled repair and concise development diagnostics. Historical results are complete; the separately frozen final1000-question evaluation has not yet been generated. The final-results section and abstract will be populated automatically from measured outputs, without method tuning, inference reruns or outcome-based selection.'
    b += [P(text),H('1. Motivation, questions and research chronology'),P('Equivalent question layouts and option rotations can change a model answer. This creates both a robustness problem and a potential ensemble resource: asking several equivalent versions may recover mistakes, but every call incurs cost. The project asks whether evolution can exploit this structure more effectively than transparent conventional controls.'),
      P('RQ1: does group-level all-presentations-correct fitness improve evolved instruction robustness beyond random search and average-accuracy fitness? RQ2: can an evolved bounded query policy trade accuracy against requested calls better than fixed subsets, greedy construction and agreement stopping? RQ3: does targeting observed mutation sites or scoring whole-policy utility improve the frozen policies beyond ordinary mutation? The final evaluation assesses these already fitted Study2 policies; it is not another search.'),
      T(['Stage','Question pool','Role'],[['Study1','ARC search128, validation100, pilot100; final1109','Initial robustness-fitness hypothesis'],['Study2','OpenBookQA search512, validation489; final486','Adaptive presentation policies'],['Controlled follow-up','Same development pools; held-out training1000','Post-result active-node/utility repair'],['Capability diagnostic','Expanded search1500, reused validation489; fact subset300','Exploratory bottleneck analysis'],['Retrieval pilot','Same1500/489 and300 controls','Negative diagnostic extension'],['Final extension','Existing reserved training1000','Frozen core-method comparison']], 'Table1. Chronology and distinct roles. Scores across different final pools are not paired improvements.',[1.1,1.9,2]),
      P('Both initial studies were completed and inspected before the repair and diagnostics. Those later analyses are explicitly exploratory, not retrospectively presented as the original hypothesis. The final comparisons were finalized after that exploration but before any reserved-question generation. The reserve is an official-training held-out subset, not the official OpenBookQA test split.'),
      H('2. Thematic related work'),H('2.1 Representations and the EC–AI connection',3),
      P('Prompt evolution is established: EvoPrompt couples LLM edits with evolutionary operators[1], and Promptbreeder also evolves mutation prompts[2]. EvoLLM studies in-context evolutionary operators[3], while EoH searches natural-language heuristic ideas and executable programs[4]. Eureka optimizes reward code[6], ADAS searches agent programs[7], and model-merging evolution changes model composition[8]. The EC–LLM survey distinguishes both directions of this interaction[9]. These works make an evolutionary wrapper alone an insufficient innovation claim. Our adaptations concern a task-specific fitness and an executable, observable-state policy with controlled mutation ablations. We implement GA-style selection/crossover/mutation and multi-objective accuracy–call selection, rather than asserting use of every course technique such as PSO or DE.'),
      H('2.2 Feedback, credit assignment and controlled operators',3),
      P('OPRO reuses scored histories to propose improvements[10]. DSPy treats LM systems as optimizable programs[11], and MIPRO studies instruction/demo optimization across modules[12]. GEPA uses reflective feedback in evolutionary improvement[5]; TextGrad propagates natural-language critiques[13]. Their strength is richer feedback than a single terminal score; their costs and representations differ substantially. This motivates testing whether search-label complementarity is useful at a query-tree mutation site, while counting every scored probe and supplying a greedy control. A locally correct response need not change the final vote: the utility repair therefore scores the complete edited policy. It remains a narrow ablation of known feedback-guided search ideas, not a general new optimizer or reproduction of these systems.'),
      H('2.3 Presentation sensitivity and useful diversity',3),
      P('FormatSpread establishes sensitivity to meaning-preserving formatting[14]. Generated answers can differ from first-token probability evaluations[15], so our strict letter-generation findings should not be transferred to likelihood scoring. Mixture-of-Agents combines model outputs[18], whereas Self-MoA cautions that source quality can offset diversity[19]. Soft self-consistency uses scoring for varied outputs[20]. Their shared lesson is that disagreement is not itself useful complementarity. A finite-bank oracle is diagnostic, not deployable. Canonical remapping, original single-format controls, exhaustive fixed subsets and simple agreement stopping are therefore necessary to determine whether an evolved ensemble adds practical value.'),
      H('2.4 Adaptive computation, routing and evidence access',3),
      P('RouteLLM learns cost-quality routing from preference data[16], and RouterBench supports cached routing evaluation[17]. Difficulty-dependent test-time compute[21] and reliability-aware self-consistency[22] show that extra computation must be allocated selectively. Earlier adaptive-consistency and FrugalGPT work already establish stopping/cascading[26,27]. Adaptive-RAG and RetrievalQA study when to retrieve[23,24]; our retrieval pilot is diagnostic and adds no adaptive-retrieval novelty. Compared with richer routers, our policies intentionally lack hidden-state confidence and question-semantic features, using only queried canonical predictions and legal observable state. This improves auditability but may restrict headroom. Cached call/token reductions do not establish live latency savings.'),
      P('The review covers24 relevant2024–2026 public works, with primary-source links and mechanism verification recorded in docs/references.json. Confirmed conference/journal records and author preprints are explicitly separated; older foundations do not count toward24. The course brief does not explicitly require all recent works to be peer-reviewed, and this report makes no such claim. Version/title discrepancies are recorded rather than silently normalized into invented publication records.',True),
      H('3. Shared model, transformations and reproducibility'),P('The target model and tokenizer revision is Qwen/Qwen2.5-3B-Instruct aa8e72537993ba99e69dfaafa59ed015b17504d1[30]. No weights are trained. Five predefined formats are original vertical choices, inline choices, bullets, and cyclic rotations by one or two positions. Canonical answer identities are the original option indices0–3. Displayed A–D letters are mapped back before voting or scoring; semantic option text is preserved. Screening excludes missing-media indicators, duplicate options, position references and exact source-question/content overlaps. Automated checks cannot guarantee absence of paraphrases or pretraining exposure.'),
      P('The fixed Study2/final manual instruction is: “Solve the science multiple-choice question carefully. Choose the single best answer based on its content, regardless of layout or option order.” The common output contract requests exactly one uppercase displayed option letter. Whitespace is trimmed; other text is invalid. Voting ignores invalid votes, resolves ties to the smallest canonical index and returns explicit failure when all queried answers are invalid. Invalid final answers count incorrect. Tie rules are fixed before final outcomes.'),
      P('Study1 used greedy BF16/SDPA target generation in batches of16 with an eight-new-token cap; its local prompt proposer sampled at temperature0.85/top-p0.95 with160-token cap. Later preparation detected batch-dependent differences. Study2, its follow-up, diagnostics and this final extension use corrected singleton generation with deterministic Torch settings, TF32 disabled, seed0 and no input truncation (1536-token input cap). Study1 results remain preserved and are not recast as singleton evidence. The final cache identity includes exact question/rendering, instruction hash, format/permutation, model/tokenizer revision and decoding configuration.'),
      H('4. Study1: evolutionary instruction optimization'),P('ARC-Challenge[29] supplies pilot100/search128 train questions,100 official-validation questions for selection and1109 screened official-test questions. The five seen formats determine fitness; a table, choices-first layout and reversed order are withheld from search/selection. An identical-input repeat is a separate stability control. Three seeds11/29/47 share initial populations of four. Every method/seed receives12800 target-evaluation calls, while original-only evaluation can examine more candidates; equal target calls are an imperfect total-compute match because proposal counts/tokens differ.'),
      T(['Condition','Search representation','Fitness'],[['A','Manual fixed instruction','No search'],['B','Independent random proposals','All-five-correct'],['C','Elitist genetic prompt search','Original accuracy'],['D','Same genetic framework','Five-format mean accuracy'],['E','Same genetic framework','All-five-correct, proposed']], 'Table2. Study1 controls separate search, augmentation exposure and robust objective.',[.6,1.7,1.7]),
      P('Local-model mutation/crossover proposes reusable instructions. Rejected, duplicate or malformed proposals and retry costs are recorded. Validation selects among the top three search candidates using the frozen criterion, then selected prompts are evaluated once. Robustness is the fraction of whole question groups correct in every seen presentation; one invalid presentation fails its group. Semantic-flip statistics use valid original/variant pairs and differ from simple displayed-letter changes.'),
      T(['Condition','Original%','Seen mean%','All-five% ± seedSD','Withheld mean%'],[[r['condition'],pct(r['original_accuracy']),pct(r['seen_average_accuracy']),pct(r['seen_all_correct'])+' ± '+pct(r['seen_all_correct_sd']),pct(r['withheld_average_accuracy'])] for r in h['study1']['summary']], 'Table3. Authoritative Study1 results on1109 questions; three fitted seeds for B–E, fixed A. SD is between search seeds, not a question interval.',[.7,1,1,1.3,1.2]),
      F(ROOT/'report/figures/study1_robustness.png','Figure1. The proposed all-presentations-correct objective E underperforms B and D. Error bars are search-seed SD.'),
      P('E achieves67.90% all-five-correct versus69.25% for random search B and69.34% for average-fitness evolution D. The saved paired E−B difference is−1.35 points (conditional95% interval−2.10 to−0.60); E−D is−1.44 points (−2.28 to−0.60). The report retains the negative objective result. Choices-first formatting creates the largest held-out-layout deterioration. Identical-input repeats show some disagreement in this batched phase, so presentation sensitivity is not a pure deterministic model property. Existing audited exact numerators, denominators, seed metrics and repeat diagnostics are preserved as supplementary data, without rerunning the301953-response audit.'),
      H('5. Study2: adaptive presentation-query policies'),P('OpenBookQA[28] supplies64 development questions,512 search questions,489 screened official-validation questions and486 screened official-test questions. Earlier ARC outcomes and later inspected OpenBookQA finals are exploratory evidence for any subsequent redesign. The instruction/model/formats are fixed. A binary query tree chooses an unused format or stops; depth≤5, query nodes≤15 and calls≤5. It can observe queried formats, canonical votes, agreement/disagreement, invalid indicators and remaining calls, never labels or unqueried predictions. Aggregation is the frozen canonical vote.'),
      P('The original random and complementary-error-guided searches use five seeds11/29/47/71/101, common populations of32 and40 generations. Crossover, representation and multi-objective accuracy-max/calls-min selection are shared. Non-dominated sorting and crowding are NSGA-II-style[25], not a faithful reference implementation: the tournament/front construction is simplified. Guided mutation favors formats rescuing search errors reaching the site when at least12 examples are available, otherwise a declared global-failure fallback. Greedy construction receives comparable search statistics;31 fixed subsets, ten triples, full-five and fixed agreement rules are controls. Validation chooses maximum accuracy under1/2/3-call allowances, then cost/size/hash; achieved final costs need not exactly equal an allowance.'),
      T(['Method','Accuracy%','Mean calls','Mean tokens'],[[r['method'],pct(r['accuracy']),f"{r['mean_calls']:.3f}",f"{r['mean_requested_tokens']:.1f}"] for r in h['study2']['summary']], 'Table4. Original Study2 primary three-call-allowance results on486 official-test questions. Five-seed methods are averaged; cross-pool differences are not repair gains.',[1.7,1,1,1]),
      P('Original rescue guidance has no observed advantage: mean accuracy81.60% at2.585 calls versus ordinary mutation81.65% at2.218. Full-five voting is worse than the selected fixed triple. These results motivated a controlled post-result repair; they did not justify claiming guidance won. A finite response bank can have oracle coverage without an observable rule identifying its correct answers.'),
      H('6. Controlled active-node and utility follow-up'),P('The follow-up reuses the512/489 development pools and freezes policies before a different1000-question held-out TRAIN subset, now already inspected. G0 preserves ordinary mutation over all sites. G1 samples only sites observed on search questions, without pruning zero-visit branches. G2 uses the same active-site rule and scores up to eight distinct whole-policy trial edits with U=accuracy−0.01×mean_calls, selecting by utility/cost/size/hash, with20% random exploration. G3 retains the original rescue heuristic; a utility hill-climber uses comparable trial statistics without evolutionary population/crossover. All five seeds share initial populations and4096 full-search-policy evaluation equivalents each. Every scored base, trial, discarded probe and duplicate is charged. Equal evaluations do not imply equal offspring: G2 can inspect fewer offspring due to lookahead.'),
      P('G2 changes bounded trial construction as well as trial ranking, so G2−G1 is an ablation of the whole informed proposal mechanism, not a perfectly isolated scorer change. Guidance uses search labels only. Frozen validation selection is the same accuracy-under-allowance rule. The new simple control enumerates all60 ordered triples, stopping only on valid agreement of the first two responses.'),
      T(['Method','Accuracy%','Calls ± seedSD','Mean tokens'],[[r['method'],pct(r['accuracy']),f"{r['mean_calls']:.4f} ± {r['mean_calls_sd']:.4f}",f"{r['mean_requested_tokens']:.1f}"] for r in h['followup']['summary'] if r['method'] in ('G0','G1','G2','G3','hill','ordered_triple','fixed_three','legacy_greedy')], 'Table5. Prior controlled follow-up on its own1000-question final pool. These are not the newly reserved final results.',[1.3,1,1.5,1]),
      F(ROOT/'report/figures/followup_calls.png','Figure2. Previous follow-up cost variation across fitted seeds; the simple ordered triple matches active-node evolution.'),
      P('Active-site mutation changed the intended search mechanism: G0 placed81.6% of mutations at sites with no observed search visits, versus0% for G1/G2. Prediction-changing edits rose from10.1% for G0 to55.9% for G1. A consequential edit is not necessarily beneficial, and zero observed visits do not prove logical unreachability. G2 spent more probes per offspring and added no observed final gain. G1, G2 and the selected ordered triple produced exactly the same answers in every fitted seed on this earlier pool, while calls differed. The G0 mean cost difference was largely driven by one seed retaining a three-call policy. Mechanism improvement and search-cost consistency are distinguished from utility-guidance effectiveness.'),
      H('7. Concise capability and retrieval diagnostics'),P('After inspecting the follow-up, development search expanded to1500 questions while validation stayed489. The currently evaluated1000-question reserve was selected first and left unqueried throughout. The old frozen reference got395/489 correct; the original five-response bank contained a correct answer for446. Its94 errors partition exactly into51 with another correct response and43 with none. This is a finite-bank selector upper bound, not deployable performance or a global model capability ceiling.'),
      P('A shared L2-regularized candidate scorer used only format support, votes, pair supports and invalid interactions, with five-fold whole-question CV confined to search. Five nested subset draws at128/256/512/1000/1500 search questions reused the same validation pool. From512 to1500, mean validation gains were only0.25 points for the three-response scorer and0.53 for five responses; at1500 they scored80.57%/three calls and80.37%/five calls, below the80.78%/2.207-call reference. Subset variation is not independent validation replication and does not establish an evolutionary learning curve.'),
      P('Three fixed original-layout strategy prompts were tested on search; a prewritten search-only rule selected elimination and principle-first for validation. They scored66.87% and65.44%, versus77.91% for the original single. About93% of their validation errors were valid parsed wrong answers, not formatting failures; neither produced truncations. On300 fixed search questions, supplying the annotated supporting fact increased original accuracy80→84%, compared with79.33% for unrelated context. This was privileged evidence. The stronger reference scored81.67% on those same300; its comparison with84% remained uncertain.'),
      P('The bounded deployable retrieval pilot indexed1326 official public science facts using fixed BM25 and a symmetric stem-plus-options query. Search selected top-one retrieval before all fixed validation conditions. It scored373/489 (76.28%), versus381/489 (77.91%) for the same-wrapper empty-evidence control and395/489 (80.78%) for ordered stopping. Top three scored380/489 (77.71%). Both retrieval conditions requested more tokens than the original one-call baseline without improving its accuracy. All annotations were in the corpus, but hit@1 was31.9% and hit@3 44.8%; matching a fact did not guarantee correct use. This negative extension motivates no automatic routing search, and contributes no evidence that evolution helps. Detailed diagnostic/control tables belong in the appendix.'),
      H('8. Final reserved-pool evaluation: frozen Study2 extension'),P('The exact existing reserve contains1000 eligible OpenBookQA training questions, dataset revision388097ea7776314e93a529163e0fea805b8a6454, reservation seed301030. Its canonical manifest hash is361ca31dacce2c25e79fcdca6af149cb64f3eec1168053cfd9263b4576df5ddb. Pre-inference checks compare known IDs, normalized stems and unordered option content against prior splits, query inventories and scoring records. Existing audited historical inventories are reused, rather than re-auditing hundreds of thousands of predictions. The same semantic-preservation rules pass all1000; no post-outcome exclusion or replacement pool is permitted.'),
      P('Frozen methods are original format, development-selected best single (rotate2), the archived fixed triple using the same formats as ordered stopping, the archived ordered triple (rotate2, rotate1, original), and all five archived G0/G1/G2 policies at the primary three-call validation allowance. Exact exports come from followup_active_utility/runs/main/FROZEN.json and its matching selected_policies.json. No cheapest/best seed is chosen. The selected exports reproduce saved validation statistics and prior answer/cost vectors before final generation.'),
      P('The primary methodological comparison is G2−G1 for accuracy, requested calls and U=accuracy−0.01×mean_calls. The primary practical comparison is ordered stopping−fixed triple, including exact answer equality and requested calls/tokens. Secondary comparisons are G1−G0, ordered stopping−original/best single, and G1/G2−ordered stopping. A three-call validation allowance is not an exact final cost constraint. Sources, prompt/renderers, exports, revisions, pool, metrics and2000-replicate bootstrap seed301050 are hashed and timestamped before the first reserved response. One five-format matrix (5000 main calls) is reused by every policy.'),
      P('Whole-question paired bootstrap retains all format responses and all five fitted seeds inside each sampled question. For seed-averaged differences, fitted-seed outcomes are averaged within question before resampling; seed SD and per-seed contrasts are separate. Intervals condition on these fitted policies and do not include uncertainty from every possible future search. Accuracy differences are percentage points; relative call/token reductions are percentages. Overlap of separate intervals is not a test, and failure to detect a difference does not establish equivalence or non-inferiority.')]
    if final:b += final_blocks(final)
    else:b += [P('Final outcomes pending. No final accuracy, winner, interval or conclusion is fabricated in this scaffold. This section will be replaced only after complete frozen-matrix generation and focused integrity checks.')]
    b += [H('9. Discussion, limitations and contribution'),P('The project connects to genetic search through population initialization, mutation, crossover and selection, and to multi-objective evolutionary optimization through accuracy–cost Pareto survival. The tested adaptations are a group-robustness fitness, complementary-error proposals, observed-state mutation locations and full-policy utility lookahead. This exceeds a bare off-the-shelf optimizer application, while the empirical conclusions remain bounded and can be negative. Neither ensembling, agreement stopping, semantic feedback nor adaptive retrieval is claimed novel.'),
      P('Keep four mechanisms separate. Ensembling may change final answers. Stopping may preserve exactly those answers while saving requests. Active-node mutation may reduce wasted edits and improve consistency across the fitted searches. Utility guidance needs its own additional benefit beyond those controls; more consequential changes or more inspected trials are insufficient evidence. A negative operator ablation is useful evidence about this design, not proof that evolution or utility search cannot work generally.'),
      P('Limitations include one small model and finite format pool; filtered public benchmarks; imperfect semantic screening and pretraining-overlap detection; different batched/singleton settings across historical phases; repeated development-validation inspection; a post-result repair; limited three/five fitted search seeds; approximate achieved costs rather than exact matching; G2 proposal-distribution confounds; and conditional rather than retraining-inclusive bootstrap intervals. The untouched final pool addresses known development exposure for this frozen comparison, not all researcher degrees of freedom. A correct annotation need not be complete evidence, and generated rationales do not reveal internal causes.'),
      H('10. Reproducibility, costs and completion'),P('The executable run script resolves its environment, one GPU, config, logging and resume paths. A launcher lock and workflow lock prevent duplicates. Singleton raw responses and durable attempts are saved after every call; cache keys include exact rendered input, instruction, permutation, model/tokenizer revision and decoding. Resume retains the same manifests and policies and rejects incompatible source/config/package changes. Complete means a full unique1000×5 matrix, consistent hashes, legal no-repeat policies, all methods on the same question IDs, reproduced replays and generated report/package artifacts. Interrupted unknown physical attempts are disclosed separately.'),
      T(['Phase','New recorded calls','Input/output tokens','Generation minutes'],[[r['phase'],str(r['calls']),f"{r['input_tokens']:,}/{r['output_tokens']:,}",f"{r['generation_seconds']/60:.2f}"] for r in h['generation_costs']], 'Table9. Actual recorded main-generation costs by phase, excluding reused calls and separate preparation extras. Batched Study1 timing is not directly comparable with singleton deployment.',[1.4,1.2,1.8,1.1]),
      P(f"Original Study2 search wall timers sum to{h['cpu_costs']['study2_recorded_search_wall_seconds']:.2f} seconds. The controlled follow-up records{h['cpu_costs']['followup_search_wall_seconds']:.2f} search wall seconds and{h['cpu_costs']['followup_search_cpu_seconds']:.2f} process-CPU seconds; durable per-evaluation checkpoint I/O accounts for much of the difference. Study1 has stage wall timings but no isolated search process-CPU timer; that legacy statistic is unavailable and is not invented. Final replay CPU/wall and matrix generation costs are measured separately in analysis/costs.json."),
      P('Actual full-matrix calls/tokens/runtime are distinct from simulated deployment calls/tokens requested by a policy and from CPU replay/document costs. Historical target/proposer/search costs are preserved separately. A full prediction cache does not by itself establish live latency savings. Ten short development-only smoke calls are extra preparation inference and do not consume the reserved pool. Model experiments and method tuning end after this final evaluation; no new search, prompts, retrieval or inference is launched from report generation.'),
      P('The submission package contains complete source/configuration, processed/raw results supporting the tables, primary-source literature records, frozen policies/manifests, figures, exact commands and a course-brief checklist. The original proposal remains unchanged; a separate one-page completed-project summary describes actual results. Nothing is submitted or published externally. Author identification/final editorial reading and the actual course upload remain the student’s tasks.'),
      H('11. Conclusion')]
    if final:
        primary=next(r for r in final['comparisons'] if r['role']=='primary_methodological');practical=next(r for r in final['comparisons'] if r['role']=='primary_practical')
        b += [P(f"Study1's proposed robust objective did not improve over its controls. Study2 and its controlled repair exposed the importance of simple stopping controls and useful mutation locations, without assuming an advantage for utility guidance. In the final frozen comparison, G2−G1 is{primary['accuracy']['difference']:+.3f} accuracy points,{primary['calls']['difference']:+.5f} calls and{primary['utility']['difference']:+.6f} utility. Ordered stopping saves{practical['calls']['relative_reduction_percent']:.2f}% of fixed-triple calls, with{final['integrity']['fixed_vote_vs_ordered_answer_differences']} different final answers. These are results for this model, pool and fitted methods, not a capability ceiling or universal evolutionary superiority claim.")]
    else:b += [P('Historical proposed methods were mixed or negative against strong controls. The final conclusion will incorporate measured reserved-pool outcomes after verification, with no outcome-based method changes.')]
    b += [H('Appendix A. Full precision, search seeds and diagnostic controls'),P('Per-seed metrics, question-paired predictions, call distributions, exact vector comparisons, raw responses, request identities, attempts, masks/costs and all paired intervals are supplied as CSV/JSON/SQLite. Printed tables round for readability; underlying values come directly from authoritative outputs, never reconstructed from rounded chat summaries.'),
      T(['Diagnostic condition','Validation correct/N','Accuracy%','Calls'],[[r['method'],f"{r['correct']}/{r['n']}",pct(r['accuracy']),f"{r['mean_calls']:.3f}"] for r in h['capability']['methods'] if r['split']=='validation' and r['method'] in ('frozen_ordered_triple','original','all_five_selector','reference_three_selector','five_plus_selected_selector','elimination','principle')], 'TableA1. Capability diagnostic on reused489 validation questions.',[2.2,1,1,.7]),
      T(['Retrieval condition','Correct/N','Accuracy%','Mean tokens'],[[r['condition'],f"{r['correct']}/{r['n']}",pct(r['accuracy']),f"{r['mean_total_tokens']:.1f}"] for r in h['retrieval']['summary'] if r['split']=='validation'], 'TableA2. Fixed retrieval-pilot conditions; R1 was selected on search, not replaced by the validation winner.',[1.5,1,1,1]),
      P('Course brief mapping: sections1–2 cover problem/motivation and a thematic review of24 recent works; sections3–6 describe the EC–AI adaptation and controlled baselines; sections7–8 separate exploratory diagnostics from final held-out assessment; sections9–10 address evidence-based interpretation, limitations and reproducibility. Source, results and supplementary materials are enumerated in submission/SUBMISSION_CHECKLIST.md.'),H('References')]
    for r in references:b += [P(f"[{r['id']}] {r['authors']} ({r['year']}). {r['title']}. {r['status']}. [Primary source]({r['url']}). "+(r['qualification'] or ''),True)]
    foundations=[(25,'Kalyanmoy Deb, Amrit Pratap, Sameer Agarwal, T. Meyarivan (2002). A fast and elitist multiobjective genetic algorithm: NSGA-II. IEEE TEC6:182–197. DOI10.1109/4235.996017.','https://www.egr.msu.edu/~kdeb/reports.shtml'),(26,'Pranjal Aggarwal, Aman Madaan, Yiming Yang, Mausam (2023). Let’s Sample Step by Step: Adaptive-Consistency for Efficient Reasoning and Coding with LLMs. EMNLP2023.','https://arxiv.org/abs/2305.11860'),(27,'Lingjiao Chen, Matei Zaharia, James Zou (2023). FrugalGPT: How to Use Large Language Models While Reducing Cost and Improving Performance. Author preprint.','https://arxiv.org/abs/2305.05176'),(28,'Todor Mihaylov, Peter Clark, Tushar Khot, Ashish Sabharwal (2018). Can a Suit of Armor Conduct Electricity? A New Dataset for Open Book Question Answering. EMNLP2018.','https://arxiv.org/abs/1809.02789'),(29,'Peter Clark et al. (2018). Think you have Solved Question Answering? Try ARC, the AI2 Reasoning Challenge. Dataset primary paper.','https://arxiv.org/abs/1803.05457'),(30,'Qwen team. Qwen2.5-3B-Instruct official model card; pinned model/tokenizer revision recorded in the experiment.','https://huggingface.co/Qwen/Qwen2.5-3B-Instruct')]
    for number,text,url in foundations:b += [P(f'[{number}] {text} [Primary record]({url}). Older foundations/assets are excluded from the24 recent-paper count.',True)]
    return b

def final_blocks(final):
    b=[H('8.1 Final achieved metrics',3)]
    b += [T(['Method','Accuracy% ± seedSD','Calls ± seedSD','Mean input/output tokens','Invalid%'],[[r['method'],pct(r['accuracy_mean'])+' ± '+pct(r['accuracy_seed_sd']),f"{r['calls_mean']:.4f} ± {r['calls_seed_sd']:.4f}",f"{r['input_tokens_mean']:.1f}/{r['output_tokens_mean']:.1f}",pct(r['invalid_mean'])] for r in final['summary']], 'Table6. Final reserved1000-question results. SD is across fitted search seeds, not across seed–question pseudo-replicates. Exact correct counts and all five seeds are in Table7/CSV.',[1.25,1.45,1.5,1.6,.8])]
    b += [T(['Method/seed','Correct/N','Calls','U','Tokens'],[[r['id'],f"{r['correct']}/{r['n']}",f"{r['mean_calls']:.4f}",f"{r['utility']:.6f}",f"{r['mean_total_tokens']:.1f}"] for r in final['per_seed']], 'Table7. Every fitted seed is retained; no seed is selected using any final pool.',[1.5,1,1,1,1])]
    distributions=[]
    for method in dict.fromkeys(r['method'] for r in final['per_seed']):
        rs=[r for r in final['per_seed'] if r['method']==method]
        distributions.append([method]+[f"{np.mean([r['calls_'+str(k)]/r['n'] for r in rs])*100:.1f}" for k in range(1,6)])
    b += [T(['Method','1 call%','2 calls%','3 calls%','4 calls%','5 calls%'],distributions,'Table7b. Distribution of requested calls; stochastic rows average fitted-seed percentages within this same question pool.',[1.4,1,1,1,1,1])]
    for filename in ('accuracy_calls.png','seed_calls.png'):
        path=ROOT/'report/figures'/filename;shutil.copy2(RUN/'analysis'/filename,path)
        b += [F(path,'Figure3. Final achieved accuracy/call trade-offs.' if filename.startswith('accuracy') else 'Figure4. Final cost for each previously fitted search seed; no new search was run.')]
    b += [T(['Role/comparison','Accuracy Δ points [95%]','Calls Δ [95%]','U Δ [95%]'],[[r['role']+': '+r['method']+' − '+r['baseline'],f"{r['accuracy']['difference']:+.3f} [{r['accuracy']['lower']:+.3f},{r['accuracy']['upper']:+.3f}]",f"{r['calls']['difference']:+.5f} [{r['calls']['lower']:+.5f},{r['calls']['upper']:+.5f}]",f"{r['utility']['difference']:+.6f} [{r['utility']['lower']:+.6f},{r['utility']['upper']:+.6f}]"] for r in final['comparisons']], 'Table8. Whole-question paired bootstrap, conditional on fitted policies. Token/input/output/invalid differences are in the supplied full-precision tables.',[1.6,1.5,1.5,1.8])]
    byid={r['id']:r for r in final['per_seed']};eq=final['exact_predictions']
    for method in ('G0','G1','G2'):
        different=sum(next(r['answer_differences'] for r in eq if {r['method'],r['baseline']}=={f'{method}/seed{seed}','ordered_triple'}) for seed in config()['search_seeds'])
        b += [P(f"{method} versus ordered stopping: {different} answer-vector differences summed across the five fitted seeds (descriptive, not independent sample size). "+('Every fitted seed produces exactly the same canonical answer vector as the simple control.' if different==0 else 'Equal rounded accuracies, where present, must not be interpreted as identical predictions.'))]
    primary=next(r for r in final['comparisons'] if r['role']=='primary_methodological');practical=next(r for r in final['comparisons'] if r['role']=='primary_practical')
    for a,other in [('G2','G1'),('G2','G0')]:
        difference=sum(next(r['answer_differences'] for r in eq if {r['method'],r['baseline']}=={f'{a}/seed{seed}',f'{other}/seed{seed}'}) for seed in config()['search_seeds'])
        b += [P(f"Matched-seed {a} versus {other}: {difference} canonical answer differences summed over five fitted seeds. "+('Their final predictions are exactly identical for every matched seed, not merely equal rounded accuracy.' if difference==0 else 'Their predictions are not exactly identical; the full paired answer vectors and seed-specific differences are retained.'))]
    b += [P(f"Primary G2−G1: accuracy{primary['accuracy']['difference']:+.3f} points, calls{primary['calls']['difference']:+.5f}, U{primary['utility']['difference']:+.6f}. "+('No observed accuracy gain is present; any utility difference must be interpreted with achieved cost.' if primary['accuracy']['difference']==0 else 'The measured accuracy and cost differences are both reported; the interval does not include search-retraining uncertainty.')),
       P(f"Primary ordered−fixed comparison: exact answer differences={final['integrity']['fixed_vote_vs_ordered_answer_differences']}; relative call reduction={practical['calls']['relative_reduction_percent']:.2f}% and relative total-token reduction={practical['tokens']['relative_reduction_percent']:.2f}%. Two valid agreeing votes cannot be overturned by one further vote under the frozen rule. This is stopping efficiency, not an additional ensemble accuracy gain."),
       P(f"Actual final matrix: {final['costs']['actual_main_cache']['calls']} calls, {final['costs']['actual_main_cache']['input_tokens']} input tokens, {final['costs']['actual_main_cache']['output_tokens']} output tokens; generation{final['costs']['actual_main_cache']['generation_seconds']/60:.2f} minutes. Raw invalid responses={final['integrity']['raw_invalid']}; truncations={final['integrity']['raw_truncated']}. These physical experiment calls are not the mean requests of an individual deployment policy.")]
    return b

def completed_summary(final=None):
    b=[H('Completed-project summary',1),P(TITLE),P('DSAI6707 Advanced Computational Intelligence | Individual project | Deadline15November2026',True),H('Question and EC adaptation'),P('Can evolving instructions or adaptive presentation-query policies improve robustness and the accuracy–cost trade-off of a frozen small LLM? Tested adaptations are all-presentations-correct fitness, error-guided mutation, observed-state mutation and complete-policy utility lookahead. Genetic operators and NSGA-II-style accuracy/call survival connect the work directly to course EC methods.'),H('Evidence from the two studies'),P('Study1: proposed robust fitness underperformed random/average-fitness controls on1109 ARC-Challenge questions. Study2: complementary-error guidance did not beat random/greedy/simple ensembles on486 OpenBookQA questions. A controlled five-seed follow-up reduced wasted mutation sites, but utility guidance added no observed benefit; simple ordered stopping matched fitted evolved answers on its earlier1000-question pool. These are bounded mixed/negative results.'),P('Development diagnostics: larger search pools modestly helped a simple selector; short reasoning instructions and fixed BM25 assistance did not beat the reference. Annotated facts helped a300-question subset, but were privileged evidence. These probes are exploratory and supply no evolutionary improvement claim.')]
    if final:
        sm={r['method']:r for r in final['summary']};c=next(r for r in final['comparisons'] if r['role']=='primary_methodological');p=next(r for r in final['comparisons'] if r['role']=='primary_practical')
        b += [H('Final frozen1000-question extension'),T(['Method','Accuracy%','Mean calls'],[[name,pct(sm[name]['accuracy_mean']),f"{sm[name]['calls_mean']:.3f}"] for name in ('original','best_single','fixed_three','ordered_triple','G0','G1','G2')], 'Previously untouched held-out OpenBookQA training subset; all five fitted G seeds retained.'),P(f"Primary G2−G1: {c['accuracy']['difference']:+.3f} accuracy points, {c['calls']['difference']:+.5f} calls, {c['utility']['difference']:+.6f} utility. Ordered versus fixed triple: {final['integrity']['fixed_vote_vs_ordered_answer_differences']} different answers and {p['calls']['relative_reduction_percent']:.2f}% fewer calls. No method was tuned after final outcomes.")]
    else:b += [H('Final extension'),P('The exact1000-question reserve and19 method/seed exports are frozen;5000 final matrix calls are planned. Final outcomes are pending, so no winner or result is invented in this scaffold.')]
    b += [H('Limits and reproducibility'),P('One model and finite formats; filtered public data and possible pretraining exposure; repeated development validation; post-result repair; few fitted search seeds; conditional question-bootstrap intervals. The reserve is not the official test split. Code, exact revisions, hashes, raw/processed results,24 recent primary-source references with status qualifications, PDF/DOCX/Markdown and a course checklist are supplied. Original proposal is preserved. No external submission or further model experiment is automated.')]
    return b

def generate(final=None):
    target=ROOT/'report';target.mkdir(parents=True,exist_ok=True);name='final_report' if final else 'draft_report';record=render(blocks(final),target/name,TITLE)
    summary=render(completed_summary(final),target/('completed_project_summary' if final else 'draft_completed_project_summary'),'Completed-project summary',one_page=True)
    atomic_json(target/('document_checks.json' if final else 'draft_document_checks.json'),{'report':record,'summary':summary,'recent_primary_works':len(read_json(ROOT/'docs/references.json')),'final_outcomes_present':final is not None})
    return record,summary
